pred_sql:
SELECT COUNT(*) as streamer_count
FROM dim_streamer
WHERE n_streams > 100;

SELECT CAST(total_watch_min AS DOUBLE) / 60 AS total_watch_hours
FROM dim_streamer
WHERE streamer = 'ninja';

WITH user_sessions AS (
  SELECT n_sessions
  FROM dim_user
)
SELECT MEDIAN(n_sessions) AS median_sessions_per_user
FROM user_sessions;

SELECT COUNT(*) as users_first_seen_after_day_30
FROM dim_user
WHERE first_day > 30;

SELECT n_viewers
FROM dws_streamer_day
WHERE streamer = 'ninja' AND day_index = 10;

SELECT COUNT(*) AS num_users
FROM dim_user
WHERE n_streamers_watched > 50;

SELECT COUNT(*) as streamers_with_more_than_100_streams
FROM dim_streamer
WHERE n_streams > 100;

SELECT CAST(total_watch_min AS DOUBLE) / 60 AS total_hours
FROM dim_streamer
WHERE streamer = 'ninja';

WITH user_sessions AS (
  SELECT user_id, n_sessions
  FROM dim_user
)
SELECT MEDIAN(n_sessions) AS median_sessions_per_user
FROM user_sessions;

SELECT active_streamers
FROM ads_platform_daily
WHERE day_index = 20;

SELECT COUNT(*) AS users_first_seen_after_day_30
FROM dim_user
WHERE first_day > 30;

SELECT n_viewers
FROM dws_streamer_day
WHERE streamer = 'ninja' AND day_index = 10;

SELECT COUNT(*) AS user_count
FROM dim_user
WHERE n_streamers_watched > 50;

SELECT COUNT(*) as streamers_with_more_than_100_streams
FROM dim_streamer
WHERE n_streams > 100;

SELECT (SUM(total_watch_min) / 60.0) AS total_hours
FROM dim_streamer
WHERE streamer = 'ninja';

WITH user_session_counts AS (
  SELECT n_sessions
  FROM dim_user
)
SELECT MEDIAN(n_sessions) AS median_sessions_per_user
FROM user_session_counts;

SELECT COUNT(*) as users_first_seen_after_day_30
FROM dim_user
WHERE first_day > 30;

SELECT n_viewers
FROM dws_streamer_day
WHERE streamer = 'ninja' AND day_index = 10;

SELECT COUNT(*) AS num_users
FROM dim_user
WHERE n_streamers_watched > 50;
